/* Receiving workflow, rack browsing and putaway selection; one domain state and one Canvas. */
(function () {
'use strict';
const Theme=window.WarehouseTheme;
const M=window.WarehouseModel, root=document.querySelector('#app'), dialog=document.querySelector('#dialog');
const icons={home:'M3 10l9-7 9 7v11h-6v-7H9v7H3z',truck:'M2 5h12v12H2zM14 10h4l4 4v3h-8M5 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4m13 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4',box:'M3 7l9-5 9 5v10l-9 5-9-5zM3 7l9 5 9-5M12 12v10M7 4l10 6',arrow:'M4 12h16m-6-6 6 6-6 6',scan:'M3 5v14M6 5v14M10 5v14M12 5v14M16 5v14M20 5v14M22 5v14',doc:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h8',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 1 1 16 0zM15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',grid:'M3 3h5v5H3zM16 3h5v5h-5zM3 16h5v5H3zM16 16h5v5h-5z',rack:'M4 3v18M20 3v18M4 8h16M4 15h16M8 4h8v4M8 10h8v5M8 17h8v4',check:'M5 12l4 4L19 6',down:'M6 9l6 6 6-6',close:'M6 6l12 12M6 18L18 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'M12 3L1 21h22zM12 9v5M12 17v1',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',filter:'M4 6h16M7 12h10M10 18h4',batch:'M9 2h6M10 2v7L4 19v3h16v-3L14 9V2M7 16h10',supplier:'M3 21V8h8v13M11 21V3h10v18M6 11h2M6 15h2M15 7h2M15 11h2M15 15h2',logout:'M9 3H3v18h6M10 12h12m-5-5 5 5-5 5',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c5 5 5 15 0 20-5-5-5-15 0-20'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.doc}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('en-US');
const button=(text,action,kind='primary',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,color='blue')=>`<span class="badge ${color}"><i></i>${esc(text)}</span>`;
let storageStatus;
try {storageStatus=M.loadState(localStorage);} catch {storageStatus=M.loadState({getItem(){throw new Error('Disabled');}});}
let storageWarning=storageStatus.warning,state=storageStatus.state||M.createState(),signedIn=false,scene=null,scenePromise=null,sceneFailed=false,toastTimer;
try {signedIn=sessionStorage.getItem('wms-demo-session')==='Conrad';}catch{}
let view='login',asn='180004521',zone='receiving',palletId='',destination='B-03-02',tab='records';
let rackScope=null,rackDetail=null,selectedLocatorId='',rackMessage='';
let rackResults=null,rackInventory=null,inventoryScope=null,rackLoading=false,rackError='',inventoryLoading=false,inventoryError='';
let rackRequest=0,inventoryRequest=0,searchRequest=0,searchLoading=false;
let rackFilters={query:'',queryType:'all',levelIndex:'',status:''};
// Ordinary local reads; tests may wrap these with controlled delay/failure. No HTTP service.
const rackReads={getRackDetail:M.getRackDetail,getLocatorInventory:M.getLocatorInventory,searchLocations:M.searchLocations};
let homeReturn=history.state?.rackReturn||null;
const selectionKey='wms-putaway-selection-v1';
let selectionContext=null,selectionMode=false,selectionNotice='',targetLocatorId='',targetTaskVersion='',pendingPutawayReturn=null;
let observedProgress;try{observedProgress=localStorage.getItem(M.STORAGE_KEY);}catch{}
function refreshProgress(){
 try{const raw=localStorage.getItem(M.STORAGE_KEY);if(raw!==observedProgress){const latest=M.restore(raw);if(!latest)throw new Error('Saved progress changed and needs recovery.');state=latest;observedProgress=raw;}}catch(error){if(error.message==='Saved progress changed and needs recovery.')throw error;}
}
function storeSelection(){try{if(selectionContext)sessionStorage.setItem(selectionKey,JSON.stringify(selectionContext));else sessionStorage.removeItem(selectionKey);}catch{}}
function clearSelection(){selectionContext=null;selectionMode=false;storeSelection();}
function selectionValid(){
 if(!selectionMode||!selectionContext)return false;
 try{refreshProgress();const result=M.validatePutawayContext(state,selectionContext);if(!result.valid)throw new Error(result.message);return true;}
 catch(error){selectionNotice=error.message+' Selection is now read-only.';clearSelection();return false;}
}
function targetValidation(){
 const j=M.getJob(state,asn),p=j?.pallets.find(p=>p.id===palletId),id=targetLocatorId||M.resolveDestination(destination);
 const context=M.validatePutawayContext(state,{asn,palletId,...window.WarehouseRackData.legacyScope,taskVersion:targetTaskVersion});
 if(!context.valid)return context;
 if(!id)return {valid:false,message:'Enter a valid location, e.g. B-03-02.'};
 return M.validatePutawayTarget(state,{asn,palletId,locatorId:id,...window.WarehouseRackData.legacyScope,taskVersion:targetTaskVersion,quantity:p?.qty,uom:'PCS'});
}
function selectionPanel(){
 if(!selectionValid())return selectionNotice?`<p class="form-error" role="status">${esc(selectionNotice)}</p>`:'';
 const c=selectionContext,p=M.getJob(state,c.asn).pallets.find(p=>p.id===c.palletId);
 const result=selectedLocatorId?M.validatePutawayTarget(state,{...c,locatorId:selectedLocatorId,quantity:p.qty,uom:'PCS'}):null;
 return `<section class="rack-selection" aria-label="Putaway selection"><h2>Choose a putaway Locator · Demo</h2><p>ASN ${esc(c.asn)} · ${esc(c.palletId)} · ${num(p.qty)} PCS · ${esc(M.getJob(state,c.asn).material)}</p><p>Original target: ${esc(c.draft.destination||'None')} · Candidate: ${esc(selectedLocator()?.locatorCode||'None')}</p><p role="status" class="${result?.valid?'green-text':'form-error'}">${esc(result?.message||'Unchecked · select a Locator to validate Demo material and capacity rules.')}</p>${button('使用此货位 / Use this Locator','use-rack-location','primary',result?.valid?'':'disabled')} ${button('Cancel selection','rack-back','secondary')}<p class="muted small">This only fills the original task. Confirm putaway there to move inventory. Local Demo rules; no ERP write or server lock.</p></section>`;
}
let filters={query:'',type:'All objects',status:'',supplier:'',from:'',to:''};
const sceneHost=document.createElement('div');sceneHost.className='viewport';
sceneHost.innerHTML=`<div data-scene-loading role="status" class="scene-loading">Building your warehouse…</div><div class="scene-caption">${icon('pin')}<span>WH-03 / HKW</span><span class="scene-live"><i></i>Illustrative view</span></div><div class="view-tools" role="group" aria-label="Warehouse view controls"><button data-scene-action="pause" aria-label="Pause animation">Ⅱ</button><span class="tool-divider"></span><button data-scene-action="zoom-out" aria-label="Zoom out">−</button><output data-zoom-value>100%</output><button data-scene-action="zoom-in" aria-label="Zoom in">+</button><button data-scene-action="reset" aria-label="Reset warehouse view">Reset view</button></div>`;
function save(){try{M.saveState(localStorage,state);observedProgress=M.serialize(state);storageWarning='';}catch{storageWarning='Progress is in memory only. Browser storage is unavailable. Export a backup before closing this page.';toast(storageWarning);}}
function progressNotice(){const unresolved=state.jobs.some(j=>j.pallets.some(p=>p.destinationStatus==='unresolved'));return storageWarning||unresolved?`<div class="storage-notice" role="status"><span>${esc(storageWarning||'Legacy destination mapping is unresolved. Progress is retained; affected ASNs cannot be submitted.')}</span>${button('Recovery / export','recover-progress','secondary')}</div>`:'';}
function recoveryDialog(){showDialog('Recover saved progress',`<p>Original v1 content is retained. Export a backup before editing. Correct the explicit Locator mapping and task/inventory pair in v2 using docs/MIGRATION-V2.md, then paste the repaired v2 JSON below. Retry reads existing storage; Reset demo requires explicit confirmation.</p>${button('Export saved data','export-progress','secondary')} ${button('Retry saved data','retry-progress','secondary')}<form id="restore-progress-form" class="operation-form"><label for="recovery-data">Repaired v2 JSON</label><textarea id="recovery-data" name="recovery" rows="8" required></textarea><p id="recovery-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">Restore repaired v2</button></form>`);}
function exportProgress(){const backup={inMemoryV2:storageStatus.blocked?null:M.serialize(state)};try{backup.savedV1=localStorage.getItem(M.LEGACY_STORAGE_KEY);backup.savedV2=localStorage.getItem(M.STORAGE_KEY);backup.initialized=localStorage.getItem(M.INITIALIZED_KEY);}catch{}const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='wms-progress-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
function job(){return M.getJob(state,asn)||state.jobs[0];}
function pallet(){return job().pallets.find(p=>p.id===palletId);}
function pickPallet(){palletId=M.currentPallet(job(),view)?.id||'';destination=M.suggestLocation(state,palletId)||'';targetLocatorId='';targetTaskVersion=M.taskVersion(job());}
function navigate(next,id=asn){if(!signedIn&&next!=='login')next='login';location.hash='#/'+next+(['unload','putaway'].includes(next)?'/'+id:'');}
function rackHash(scope,id=''){const params=new URLSearchParams({org:scope.organizationId});if(scope.subinventoryId)params.set('sub',scope.subinventoryId);if(id)params.set('locator',id);if(selectionMode)params.set('mode','select');return '#/rack/'+encodeURIComponent(scope.physicalRackId)+'?'+params;}
function openRack(physicalRackId){
 if(view==='putaway'){
  try{refreshProgress();const context={asn,palletId,...window.WarehouseRackData.legacyScope,taskVersion:targetTaskVersion,returnTo:'#/putaway/'+asn,
   originalTarget:{locatorId:targetLocatorId||M.resolveDestination(destination),destination},draft:{destination,scan:document.querySelector('#scan-input')?.value||'',tab},
   scene:scene?.getViewState(),zone,scrollTop:document.querySelector('#page-content')?.scrollTop||0,scrollY};
   const valid=M.validatePutawayContext(state,context);if(!valid.valid)throw new Error(valid.message);
   selectionContext=context;selectionMode=true;selectionNotice='';storeSelection();
  }catch(error){return actionError(error);}
 }else {clearSelection();selectionNotice='';}
 location.hash=rackHash({physicalRackId,...window.WarehouseRackData.legacyScope});
}
function returnFromRack(use=false){
 if(selectionValid()){
  const c=selectionContext;
  if(use){const p=M.getJob(state,c.asn).pallets.find(p=>p.id===c.palletId),result=M.validatePutawayTarget(state,{...c,locatorId:selectedLocatorId,quantity:p.qty,uom:'PCS'});
   if(!result.valid){rackMessage=result.message;render();return;}
   c.draft.destination=result.destinationCode;c.originalTarget={locatorId:result.locatorId,destination:result.destinationCode};
  }
  pendingPutawayReturn=c;clearSelection();location.hash=c.returnTo;
 }else {if(use){render();return;}clearSelection();navigate('home');}
}
function selectedLocator(){return rackDetail?.locators.find(l=>l.locatorId===selectedLocatorId)||rackResults?.locations.find(l=>l.locatorId===selectedLocatorId);}
function selectLocator(id){
 if(view!=='rack')return;
 const l=rackDetail?.locators.find(l=>l.locatorId===id)||rackResults?.locations.find(l=>l.locatorId===id);
 if(!l)return;
 ++rackRequest;
 const mapping=l.mapping===undefined?M.getLocatorMapping(l):l.mapping;
 selectedLocatorId=id;inventoryScope={organizationId:l.organizationId,subinventoryId:l.subinventoryId,locatorId:id};
 rackMessage=!mapping?'No physical mapping. Inventory is available in the list; no coordinates are inferred.':'';
 if(!rackResults?.locations.some(item=>item.locatorId===id)){
  rackFilters={query:'',queryType:'all',levelIndex:'',status:''};loadRackResults();
 }
 if(mapping&&mapping.physicalRackId!==rackDetail?.rack.id){
  // Scope-wide results keep their list while a mapped selection opens its actual rack.
  loadSelectedRack(mapping.physicalRackId);
 }
 if(!mapping){if(!rackDetail?.errors.length)rackDetail=null;render();}
 history.replaceState(history.state,'',rackHash(rackScope,id));scene?.selectLocator(id);syncRackSelection();loadInventory();
}
async function loadSelectedRack(id){
 const request=++rackRequest,scope={...rackScope,physicalRackId:id};
 try{const detail=await rackReads.getRackDetail(scope,state);if(view!=='rack'||request!==rackRequest)return;
  rackDetail=detail;rackError='';render();
 }catch(error){if(view==='rack'&&request===rackRequest){rackDetail=null;rackError=error.message;render();}}
}
function locatorStatus(id){const s=rackDetail?.states.find(s=>s.locatorId===id)||rackResults?.locations.find(l=>l.locatorId===id)?.state;return !s?'Unknown':s.availability==='blocked'?'Disabled':s.availability==='unknown'||s.occupancy==='unknown'?'Unknown':s.occupancy==='occupied'?'Occupied':'Empty';}
function inventoryTable(lines){
 return `<div class="inventory-table-wrap" tabindex="0" role="region" aria-label="Inventory rows"><table class="inventory-table"><thead><tr>${['Material / lot','Quantity / UOM','Pallet / updated'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${lines.map(l=>`<tr><td><b>${esc(l.materialId)}</b><small>${esc(l.materialName)}<br>Lot ${esc(l.lot||'—')}</small></td><td>${num(l.quantity)} ${esc(l.uom)}</td><td>${esc(l.palletId||'—')}<small>${esc(l.asOf||'Unknown update time')}<br>${esc(l.source)}</small></td></tr>`).join('')}</tbody></table></div>`;
}
function inventoryInfo(){
 if(inventoryLoading&&!rackInventory)return '<p role="status">Loading inventory…</p>';
 if(inventoryError)return `<p class="form-error" role="alert">Inventory unknown: ${esc(inventoryError)}</p>${button('Retry inventory','retry-inventory','secondary')}`;
 if(!rackInventory)return '';
 const data=rackInventory,units=new Map();data.inventoryLines.forEach(l=>units.set(l.uom,(units.get(l.uom)||0)+l.quantity));
 return `<h3>Inventory details · ${data.inventoryLines.length} rows loaded</h3><p class="inventory-completeness">${data.nextCursor?'More rows available · loaded rows only':data.complete?'Complete Demo snapshot':'Inventory unknown / incomplete data · known rows only'}</p><p class="small">${[...units].map(([uom,qty])=>num(qty)+' '+esc(uom)).join(' · ')||'No known quantity'}</p>${data.inventoryLines.length?inventoryTable(data.inventoryLines):`<p>${data.complete?(data.filtered?'No matching inventory rows.':'No inventory in this complete snapshot.'):'No known rows; this does not mean empty.'}</p>`}${data.nextCursor?button(inventoryLoading?'Loading…':'Load more inventory','more-inventory','secondary',inventoryLoading?'disabled':''):''}<p class="muted small">${esc(data.source)} · Updated ${esc(data.asOf||'unknown')} · ${esc(data.revision||'unknown revision')}</p>${button('Refresh inventory','retry-inventory','secondary')}`;
}
function locatorInfo(){
 const l=selectedLocator(),sub=window.WarehouseRackData.subinventories.find(s=>s.id===inventoryScope?.subinventoryId);
 const org=window.WarehouseRackData.organizations.find(o=>o.id===inventoryScope?.organizationId);
 return l||inventoryScope?.locatorId===null?`<h3>${l?'Selected Locator':'Subinventory inventory'}</h3><h2>${esc(l?.locatorCode||sub?.code)}</h2><dl class="rack-facts">${[['Organization',org?.code+' / '+inventoryScope.organizationId],['Subinventory',sub?.code+' / '+inventoryScope.subinventoryId],...(l?[['Rack',l.segments.rack],['Row',l.segments.row],['Bin',l.segments.bin],['Status',locatorStatus(l.locatorId)],['Storage mode',l.storageMode],['Special pallet number',l.specialPalletNumber??'Not defined']]:[])].map(([key,value])=>`<div><dt>${key}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p class="muted small">${selectionMode?'Demo inventory · candidate eligibility is shown in the task panel.':'Read-only Demo · Putaway eligibility unchecked.'}</p>${inventoryInfo()}`:'<h3>Locator information</h3><p class="muted">Select a mapped compartment or use the Locator list below.</p>';
}
async function loadInventory(more=false){
 if(!inventoryScope)return;
 const focus=rackFocus();
 const request=++inventoryRequest,scope={...inventoryScope,...(inventoryScope.locatorId===null?{query:rackFilters.query,queryType:rackFilters.queryType}:{}),...(more?{cursor:rackInventory?.nextCursor}:{})};
 if(!more)rackInventory=null;inventoryLoading=true;inventoryError='';syncRackSelection();
 try{const result=await rackReads.getLocatorInventory(scope,state);if(view!=='rack'||request!==inventoryRequest)return;
  rackInventory=more?{...result,inventoryLines:[...rackInventory.inventoryLines,...result.inventoryLines]}:result;
 }catch(error){if(request!==inventoryRequest||view!=='rack')return;inventoryError=error.message;}
 inventoryLoading=false;syncRackSelection();
 if(focus&&document.activeElement.id==='rack-locator-info')document.querySelector(focus)?.focus({preventScroll:true});
}
async function loadRackResults(more=false){
 searchLoading=true;
 const request=++searchRequest,scope={...rackScope,...rackFilters,levelIndex:rackFilters.levelIndex===''?undefined:Number(rackFilters.levelIndex),...(more?{cursor:rackResults?.nextCursor}:{})};
 render();
 try{const result=await rackReads.searchLocations(scope,state);if(view!=='rack'||request!==searchRequest)return;
  rackResults=more?{...result,locations:[...rackResults.locations,...result.locations]}:result;rackError='';
 }catch(error){if(view!=='rack'||request!==searchRequest)return;rackResults=null;rackError=error.message;}
 searchLoading=false;render(true);
}
async function loadRackPage(){
 const request=++rackRequest,scope={...rackScope};++searchRequest;++inventoryRequest;
 rackDetail=null;rackResults=null;rackInventory=null;inventoryScope=null;inventoryError='';rackError='';rackLoading=true;searchLoading=false;render();
 try{
  const [detailRead,resultRead]=await Promise.allSettled([
   Promise.resolve().then(()=>scope.physicalRackId?rackReads.getRackDetail(scope,state):null),
   Promise.resolve().then(()=>rackReads.searchLocations({...scope,...rackFilters,levelIndex:rackFilters.levelIndex===''?undefined:Number(rackFilters.levelIndex)},state))]);
  if(view!=='rack'||request!==rackRequest)return;
  rackDetail=detailRead.status==='fulfilled'?detailRead.value:null;
  rackResults=resultRead.status==='fulfilled'?resultRead.value:null;rackLoading=false;
  rackError=[detailRead,resultRead].filter(r=>r.status==='rejected').map(r=>r.reason.message).join(' · ');
  if(!rackResults&&rackDetail)rackDetail={...rackDetail,complete:false,states:rackDetail.states.map(s=>({...s,occupancy:'unknown',complete:false}))};
  const l=selectedLocator();
  rackMessage=selectedLocatorId&&!l?'Requested Locator is unavailable in this rack and scope.':'';
  if(rackMessage)selectedLocatorId='';
  if(l)inventoryScope={organizationId:l.organizationId,subinventoryId:l.subinventoryId,locatorId:l.locatorId};
  const sub=window.WarehouseRackData.subinventories.find(s=>s.id===scope.subinventoryId&&s.organizationId===scope.organizationId);
  if(!scope.physicalRackId&&sub?.locatorEnabled!==true&&sub)inventoryScope={...scope,locatorId:null};
  render();if(inventoryScope)loadInventory();
  if(!scope.physicalRackId&&l?.mapping)loadSelectedRack(l.mapping.physicalRackId);
 }catch(error){if(view!=='rack'||request!==rackRequest)return;rackLoading=false;rackError=error.message;render();}
}
function syncRackSelection(){
 const focus=rackFocus();
 const selection=document.querySelector('#rack-selection');if(selection)selection.innerHTML=selectionPanel();
 const info=document.querySelector('#rack-locator-info');if(info)info.innerHTML=locatorInfo();
 document.querySelectorAll('[data-locator-id]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.locatorId===selectedLocatorId)));
 const note=document.querySelector('#rack-message');if(note)note.textContent=rackMessage;
 const announcement=document.querySelector('#rack-announcement');if(announcement)announcement.textContent=rackAnnouncement();
 document.querySelectorAll('[data-action="focus-inventory"]').forEach(b=>b.disabled=!inventoryScope);
 restoreRackFocus(focus);
}
function rackAnnouncement(){
 const l=selectedLocator();
 return `${l?'Selected '+l.locatorCode+' · '+locatorStatus(l.locatorId)+'. ':''}${inventoryLoading?'Loading inventory.':inventoryError?'Inventory unavailable. Retry available.':rackInventory?rackInventory.inventoryLines.length+' inventory rows loaded.':searchLoading||rackLoading?'Loading locations.':(rackResults?.total??0)+' matching locations.'}`;
}
function rackFocus(){
 const el=document.activeElement;if(!el?.closest('.rack-content'))return null;
 if(el.id)return '#'+CSS.escape(el.id);
 if(el.dataset.locatorId)return '[data-locator-id="'+CSS.escape(el.dataset.locatorId)+'"]';
 if(el.name)return '#rack-filter-form [name="'+CSS.escape(el.name)+'"]';
 if(el.dataset.action)return '.rack-content [data-action="'+CSS.escape(el.dataset.action)+'"]';
 if(el.dataset.sceneAction)return '.rack-content [data-scene-action="'+CSS.escape(el.dataset.sceneAction)+'"]';
 if(el.matches('.inventory-table-wrap'))return '#rack-locator-info .inventory-table-wrap';
 if(el.matches('[type="submit"]'))return '#rack-filter-form [type="submit"]';
 return null;
}
function restoreRackFocus(selector){
 if(selector&&!document.activeElement?.closest('.rack-content'))
  (document.querySelector(selector)||document.querySelector('#rack-locator-info'))?.focus({preventScroll:true});
}
const rackOptions=(items,value)=>items.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('');
function rackControls(){
 const catalog=window.WarehouseRackData,subs=catalog.subinventories.filter(s=>s.organizationId===rackScope.organizationId);
 let racks=[];try{racks=M.listRacks({...rackScope,subinventoryId:rackScope.subinventoryId||undefined});}catch{}
 return `<form id="rack-filter-form" class="rack-filters"><label>Organization<select name="organizationId" id="rack-org" ${selectionMode?'disabled':''}>${rackOptions(catalog.organizations.map(o=>[o.id,o.code+' · '+o.name]),rackScope.organizationId)}</select></label><label>Subinventory<select name="subinventoryId" id="rack-sub" ${selectionMode?'disabled':''}>${rackOptions([['','All subinventories'],...subs.map(s=>[s.id,s.code+' · '+s.name])],rackScope.subinventoryId||'')}</select></label><label>Rack<select name="physicalRackId" id="rack-physical">${rackOptions([['','All locations / unmapped'],...racks.map(r=>[r.id,r.label])],rackScope.physicalRackId)}</select></label><label>Level<select name="levelIndex">${rackOptions([['','All levels'],...(rackDetail?.rack.levels||[]).map(l=>[String(l.levelIndex),'L'+(l.levelIndex+1)])],rackFilters.levelIndex)}</select></label><label>Status<select name="status">${rackOptions([['','All states'],['occupied','Occupied'],['empty','Empty'],['disabled','Disabled'],['unknown','Unknown']],rackFilters.status)}</select></label><label>Search by<select name="queryType">${rackOptions([['all','All objects'],['locator','Locator'],['material','Material'],['pallet','Pallet']],rackFilters.queryType)}</select></label><label class="rack-query">Search inventory<input name="query" value="${esc(rackFilters.query)}" placeholder="Locator, material or pallet"></label><button class="btn primary" type="submit" ${rackLoading?'disabled':''}>Search / apply</button>${button('Refresh data','refresh-rack','secondary')}</form>`;
}
function rackSummary(){
 const s=rackResults?.summary;
 return s?`<section class="rack-summary" aria-label="Scope inventory summary">${[['Scope Locators',s.total],['Mapped',s.mapped],['Unmapped',s.unmapped],['Occupied',s.occupied],['Empty',s.empty],['Disabled',s.disabled],['Unknown',s.unknown],['货位占用比例',s.occupancyRatio!==null?(s.occupancyRatio*100).toFixed(1)+'%':s.complete?'—':'待同步']].map(([key,value])=>`<div><small>${key}</small><b>${value}</b></div>`).join('')}<p class="muted small">Scope-wide summary · Search, level, rack and status filters do not change the denominator. Active occupied ${s.activeOccupied} / active ${s.active}. Updated ${esc(rackResults.asOf)}</p></section>`:'';
}
function rackList(){
 const catalog=window.WarehouseRackData,sub=catalog.subinventories.find(s=>s.id===rackScope.subinventoryId&&s.organizationId===rackScope.organizationId);
 const results=rackResults,locations=results?.locations||[];
 const branch=sub?.locatorEnabled===false?'Locator disabled · Subinventory-level inventory; no positions are invented.':sub?.locatorEnabled===null?'Locator configuration pending confirmation · inventory unknown.':sub?.locatorEnabled===true&&!M.listLocators(rackScope).length?'Locators enabled, but no location data is configured.':'';
 return `<section class="rack-list-section" aria-busy="${searchLoading}">${searchLoading?'<p role="status">Loading matching locations…</p>':''}<h2>Locator list <small>${results?.total??0} results</small></h2><p class="muted small">${esc(branch||'Select a result to view all materials, lots and pallets. Unmapped / non-rack locations remain list-only.')}</p>${!locations.length&&!rackLoading&&!rackError?'<p role="status">No matching locations.</p>':''}<ul class="rack-locator-list" aria-label="Mapped Locators">${locations.map(l=>`<li><button data-action="select-locator" data-locator-id="${esc(l.locatorId)}" aria-pressed="${selectedLocatorId===l.locatorId}"><b>${esc(l.locatorCode)}</b><span>${esc(l.organizationId)} / ${esc(l.subinventoryId)}<br>Rack ${esc(l.segments.rack)} / Row ${esc(l.segments.row)} / Bin ${esc(l.segments.bin)}<br>${l.mapping?esc(l.mapping.physicalRackId)+' · L'+(l.mapping.levelIndex+1):'Unmapped / non-rack · no coordinates'}</span><span class="rack-status ${locatorStatus(l.locatorId).toLowerCase()}">${locatorStatus(l.locatorId)}</span></button></li>`).join('')}</ul>${button('View inventory details','focus-inventory','secondary',`aria-controls="rack-locator-info" ${inventoryScope?'':'disabled'}`)}${results?.nextCursor?button('Load more results','more-results','secondary'):''}${results?.unresolvedLines.length?`<h3>Unresolved legacy placements · no coordinates</h3>${inventoryTable(results.unresolvedLines)}<p class="muted small">${results.unresolvedLines.map(l=>esc(l.legacyDestination)+' · '+esc(l.palletId)).join(' / ')} · Mapping pending; scope inventory is incomplete.</p>`:''}</section>`;
}
function rackPage(){
 const selection=selectionPanel();
 const detail=rackDetail,rack=detail?.rack,configured=rack?.layoutStatus==='configured'&&!detail.errors.length;
 const org=window.WarehouseRackData.organizations.find(o=>o.id===rackScope?.organizationId);
 const sub=window.WarehouseRackData.subinventories.find(s=>s.id===rackScope?.subinventoryId&&s.organizationId===rackScope?.organizationId);
 return `<section class="rack-content"><div class="rack-heading"><div><div class="eyebrow">WAREHOUSE / ${selectionMode?'PUTAWAY SELECTION':'READ-ONLY'} DEMO</div><h1 id="rack-title" tabindex="-1">${rack?esc(rack.label):rackScope.physicalRackId?'Rack unavailable':'Inventory browser'}</h1><p class="muted">${esc(org?.name||rackScope?.organizationId)} / ${esc(sub?.name||rackScope?.subinventoryId||'All subinventories')} · scene-demo</p></div>${button(selectionMode?'← Cancel / Return to putaway':'← Return to overview','rack-back','secondary')}</div><div id="rack-selection">${selection}</div>${rackControls()}<p id="rack-announcement" class="sr-only" role="status" aria-atomic="true">${esc(rackAnnouncement())}</p><p id="rack-message" class="rack-message" role="status">${esc(rackMessage)}</p>${rackLoading?'<p role="status">Loading inventory scope…</p>':''}${rackError?`<p class="form-error" role="alert">Data unavailable / inventory unknown: ${esc(rackError)}</p>${button('Retry data','refresh-rack','secondary')}`:''}${rackSummary()}${configured?`<div class="rack-browser"><section class="rack-drawing" aria-label="Rack structure">${sceneSlot()}<div class="rack-legend">${['Occupied','Empty','Disabled','Unknown','Unconfigured'].map(s=>`<span class="rack-status ${s.toLowerCase()}"><i></i>${s}</span>`).join('')}</div><p class="muted small">${rack.levels.length} levels · ${detail.mappings.length} mapped Locators · Drag to pan, scroll to zoom. Nonmatching positions are dimmed; Small labels hide when space is limited; full codes remain in the list. Row / Bin use explicit Demo mappings.</p></section><aside id="rack-locator-info" class="rack-locator-info" tabindex="-1" aria-label="Inventory details">${locatorInfo()}</aside></div>`:`${rackScope.physicalRackId&&!rackLoading?`<div class="rack-unavailable"><h2>${rack?(detail.errors.length?'Layout unavailable':'Layout pending configuration'):'Rack unavailable in this scope'}</h2><p>${rack?(detail.errors.length?'The layout could not be validated. No selectable positions are drawn.':'This Demo rack has no configured layout. Unconfigured positions are not empty Locators.'):'Check the rack ID, inventory organization and subinventory in the link.'}</p>${button('Return to overview','rack-back','secondary')}</div>`:''}<aside id="rack-locator-info" class="rack-locator-info" tabindex="-1" aria-label="Inventory details">${locatorInfo()}</aside>`}${rackList()}<p class="rack-source muted small">Demo catalog + saved v2 inventory · ${esc(rackResults?.asOf||window.WarehouseRackData.asOf)} · Local sample inventory; eligibility unchecked.</p></section>`;
}
function themePicker(){return `<details class="theme-menu"><summary aria-label="主题 / Theme"><span class="theme-dot" aria-hidden="true"></span><span>主题</span>${icon('down')}</summary><div class="theme-popover"><h2>主题配色 <span class="muted">/ Appearance</span></h2><p>选择后立即应用，自动记住你的偏好。</p><div class="theme-options" role="group" aria-label="主题配色">${Object.values(Theme.themes).map(t=>`<button type="button" class="theme-card" data-action="theme" data-theme-id="${t.id}" aria-pressed="${Theme.current.id===t.id}" aria-label="${t.name} ${t.english}" style="${['bg','surface','header','sidebar','border','primary'].map(key=>'--preview-'+key+':'+t.tokens[key]).join(';')}"><span class="theme-preview" aria-hidden="true"><span class="theme-preview-header"></span><span class="theme-preview-rail"><i></i></span><span class="theme-preview-body"><i></i><i></i><i></i></span></span><b>${t.name}</b><small>${t.english}</small><span class="theme-selected">${Theme.current.id===t.id?icon('check')+'当前使用':''}</span></button>`).join('')}</div></div></details>`;}
function header(){return `<header class="topbar"><a href="#/${signedIn?'home':'login'}" class="brand"><strong>WMS</strong><span>ACTION WORKBENCH</span></a>${signedIn?`<span class="header-warehouse">WH-03 <span>/ HKW</span></span>`:''}<div class="header-right">${themePicker()}${signedIn?`<button class="plain module-button" data-action="modules">${icon('grid')}<span>All modules</span>${icon('down')}</button>`:''}<span class="environment">UAT${signedIn?' · Sample data':''}</span>${signedIn?`<details class="account-menu"><summary><span class="avatar">C</span><b>Conrad</b>${icon('down')}</summary><div class="menu-popover"><small>CONRAD HUA · OPERATOR</small>${button(icon('home')+' Home','home','plain')}${button(icon('clock')+' Reset demo','reset','plain')}${button(icon('logout')+' Sign out','logout','plain')}</div></details>`:`<span class="language">${icon('globe')} English</span>`}</div></header>`;}
function login(){return `${header()}<main class="login-layout"><section class="login-visual"><div class="login-copy"><h1>Warehouse operations, <em>connected.</em></h1><p>Real-time visibility across receiving, storage and dispatch.</p></div><img class="login-art" src="${Theme.current.image}" alt="Cutaway warehouse with loading docks, storage racks and pallet handling"><div class="login-visual-foot"><span>ONE WORKSPACE. EVERY MOVEMENT.</span><span>RECEIVE ${icon('arrow')} STORE ${icon('arrow')} DISPATCH</span></div></section><section class="login-panel"><div class="login-form-wrap"><div class="eyebrow">WMS ACCESS</div><h2>Sign in to your workspace</h2><p class="muted">Use your WMS demo account to continue.</p><form id="login-form"><label for="username">Username</label><input id="username" name="username" value="conrad.hua" autocomplete="username" required><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" value="demo123" autocomplete="current-password" required><button type="button" class="plain" data-action="password" aria-label="Show password">${icon('eye')}</button></div><label for="environment">Connect to</label><select id="environment"><option>UAT</option></select><p id="login-error" class="form-error" role="alert"></p><button class="btn primary sign-in" type="submit">Sign in ${icon('arrow')}</button></form><button class="text-link" data-action="forgot">Forgot password via Oracle EBS</button><p class="demo-credentials">Demo access · conrad.hua / demo123</p><div class="login-security"><span>User Acceptance Testing</span><div><b class="macnica">MACNICA</b><span>WMS · Secure access</span></div></div></div></section></main>`;}
const navItem=(text,name,glyph,shortcut='')=>`<a class="nav-item ${view===name?'selected':''}" href="#/${name}" ${view===name?'aria-current="page"':''}>${icon(glyph)}<span>${text}</span>${shortcut?`<kbd>${shortcut}</kbd>`:''}</a>`;
function rail(){return `<aside class="sidebar"><nav aria-label="Main navigation">${navItem('Home','home','home','F1')}<a class="nav-item ${view!=='home'&&view!=='rack'?'selected':''}" href="#/receiving">${icon('truck')}<span>Inbound</span><kbd>F2</kbd></a>${view!=='home'&&view!=='rack'?`<div class="subnav"><a class="${view==='receiving'?'active':''}" href="#/receiving">Receiving Job Search</a><button data-action="unavailable" data-name="RMA Search">RMA Search</button><button data-action="unavailable" data-name="Location Preference">Location Preference</button></div>`:''}<button class="nav-item" data-action="zone" data-zone="dispatch">${icon('arrow')}<span>Outbound</span><kbd>F3</kbd></button><button class="nav-item" data-action="zone" data-zone="storage">${icon('box')}<span>Storage</span><kbd>F4</kbd></button></nav>${['unload','putaway'].includes(view)?`<section class="work-steps"><h3>Work steps</h3><button data-action="step" data-view="unload" class="step-link ${view==='unload'?'active':''}"><i>${M.totals(job()).remainingUnload?'1':icon('check')}</i>Unload</button><button data-action="step" data-view="putaway" class="step-link ${view==='putaway'?'active':''}" ${M.totals(job()).remainingUnload?'disabled':''}><i>${M.stage(job())==='complete'?icon('check'):'2'}</i>Putaway</button><span class="step-link muted"><i>3</i>Confirmation <small>Pending</small></span></section>`:`<button class="all-modules" data-action="modules">${icon('grid')}All modules</button>`}<section class="recent-work"><h3>Recent work</h3><button data-action="recent-asn"><span class="recent-icon">${icon('doc')}</span><span><b>${asn}</b><small>Inbound · ${esc(job().supplier)}</small></span></button><button data-action="object" data-object="PAL-004281"><span class="recent-icon">${icon('scan')}</span><span><b>PAL-004281</b><small>Pallet · MAT-2048</small></span></button><button data-action="object" data-object="MAT-2048"><span class="recent-icon">${icon('box')}</span><span><b>MAT-2048</b><small>Widget Assembly</small></span></button></section><div class="sidebar-foot"><span class="status-dot"></span> Local demo<span>28 OCT 2026 · WH-03</span></div></aside>`;}
function scanBar(){const operation=['unload','putaway'].includes(view);return `<form class="scanbar" id="scan-form">${icon('scan','scan-icon')}<div class="scan-field"><label for="scan-input">${operation?'Scan carton or pallet ID':view==='receiving'?'Scan or enter ASN / Job ID':'Scan or enter an ID'}</label><input id="scan-input" name="scan" value="${esc(operation?palletId:filters.query)}" placeholder="${operation?'Scan a pallet ID':view==='receiving'?'ASN, job, PO or material ID':'Scan or enter an ID'}" autocomplete="off"><button type="button" class="plain clear-scan" data-action="clear-scan" aria-label="Clear scanned ID">${icon('close')}</button></div><select name="scanType" aria-label="Object type">${(operation?['Pallet']:['All objects','ASN','Job']).map(x=>`<option ${x===filters.type?'selected':''}>${x}</option>`).join('')}</select><button class="btn scan-submit" type="submit" aria-label="Find scanned object">${icon('search')}</button>${view==='home'?`<div class="scan-warehouse">${icon('home')}<span><small>Warehouse</small><b>WH-03 / HKW</b></span></div>`:`<div class="scan-hint">${icon('scan')} Scan ID, then press Enter</div>`}</form>`;}
const sceneSlot=()=>'<div class="scene-slot" data-scene-slot></div>';
function zoneTabs(){return `<div class="zone-tabs" role="group" aria-label="Warehouse zone">${[['receiving','Inbound','truck'],['storage','Storage','box'],['dispatch','Outbound','arrow']].map(([id,name,glyph])=>`<button data-action="zone" data-zone="${id}" aria-pressed="${zone===id}" class="${zone===id?'active':''}">${icon(glyph)}${name}</button>`).join('')}</div>`;}
function home(){const inbound=zone==='receiving',title=inbound?'Inbound':zone==='storage'?'Storage':'Outbound';const functions=inbound?['Receiving Job Search','RMA Search','Return Material Authorization','Location Preference','Vendor Label Rule Mapping','Import Declaration']:zone==='storage'?['On-hand Inventory','Location Preference','Cycle Count']:['Shipment Search','Picking','Packing & Dispatch'];return `<section class="home-content"><div class="home-main"><div class="overview-heading"><div><h1>Warehouse overview</h1><p class="muted">Select a zone, or click a rack to browse its layout.</p></div><div class="overview-metrics"><div>${icon('truck')}<span>Pending receipts<b>${12}</b></span></div><div>${icon('arrow')}<span>Pending shipments<b>8</b></span></div><div>${icon('rack')}<span>Storage occupancy<b>84<small>%</small></b></span></div></div></div>${sceneSlot()}${zoneTabs()}</div><aside class="context home-context"><div class="context-title"><h2>${title}</h2><span class="badge current-zone">Selected zone</span></div><div class="zone-counts">${(inbound?[['Unload',state.jobs.filter(j=>M.stage(j)==='unload').length+4],['Putaway',state.jobs.filter(j=>M.stage(j)==='putaway').length+1],['Confirm',state.jobs.filter(j=>M.stage(j)==='complete').length+1]]:[['Active',zone==='storage'?'21':'8'],['Waiting',zone==='storage'?'4':'3'],['Complete',zone==='storage'?'12':'5']]).map(([name,count])=>`<div><span>${name}</span><b>${count}</b></div>`).join('')}</div><h3>Available functions</h3><div class="function-list">${functions.map((name,i)=>`<button data-action="${name==='Receiving Job Search'?'receiving':name==='On-hand Inventory'?'inventory-browser':'unavailable'}" data-name="${name}" class="${i===0?'highlight':''}">${icon(name.includes('Location')?'pin':'doc')}<span>${name}</span>${icon('arrow')}</button>`).join('')}</div><div class="section-heading"><h3>Recent receipts</h3><button class="text-link" data-action="receiving">View all</button></div>${state.jobs.slice(0,2).map(j=>`<button class="receipt-link" data-action="open-job" data-asn="${j.asn}">${icon('doc')}<span><b>ASN ${j.asn}</b><small class="${M.stage(j)==='unload'?'green-text':'blue-text'}"><i class="status-dot"></i>${M.stage(j)==='unload'?'Ready to unload':M.stage(j)==='putaway'?'Putaway in progress':'SAP confirmation pending'}</small></span>${icon('arrow')}</button>`).join('')}<section class="home-rack-links"><h3>Rack browsing <small>Demo</small></h3>${button('Browse inventory / scopes','inventory-browser','secondary')}<p class="muted small">Two configured structures; other racks show layout status.</p>${['b02','b03'].map(id=>button(id==='b02'?'B-02 · 4 levels':'B-03 · 3 levels','open-rack','secondary',`data-rack-id="rack-demo-${id}"`)).join('')}</section></aside></section>`;}
function jobBadge(j){return badge(M.status(j),M.status(j)==='Ready'?'green':M.status(j)==='Scheduled'?'gray':M.status(j)==='SAP pending'?'amber':'blue');}
function detailList(j){const t=M.totals(j);return `<dl class="detail-list"><div><dt>${icon('pin')}Warehouse</dt><dd>${esc(j.warehouse)}</dd></div><div><dt>${icon('doc')}PO number</dt><dd>${esc(j.po)}</dd></div><div><dt>${icon('box')}Expected quantity</dt><dd>${num(t.expected)} PCS</dd></div><div><dt>${icon('rack')}Cartons</dt><dd>${t.cartons} cartons (${j.pallets.length} pallets)</dd></div></dl>`;}
function receiving(){const rows=M.searchJobs(state,filters),j=job(),t=M.totals(j),selected=rows.some(r=>r.asn===asn);return `<section class="receiving-content"><div class="page-heading"><div><div class="eyebrow">INBOUND OPERATIONS</div><h1>Receiving Job Search</h1></div><span class="quiet-label">Find a job. Keep goods moving.</span></div><form id="filter-form" class="filters"><label>Warehouse<select name="warehouse"><option>HKW</option></select></label><label>Status<select name="status"><option value="">All active</option>${['Ready','In progress','Scheduled','SAP pending'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Supplier<select name="supplier"><option value="">All suppliers</option>${[...new Set(state.jobs.map(j=>j.supplier))].map(x=>`<option ${filters.supplier===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="date-filter">Date range<div><input type="date" name="from" aria-label="Start date" value="${esc(filters.from)}"><span>→</span><input type="date" name="to" aria-label="End date" value="${esc(filters.to)}"></div></label><button class="btn primary" type="submit">${icon('search')}Search</button><button type="button" class="text-link" data-action="clear-filters">Clear</button></form><div class="receiving-grid"><section class="results"><div class="table-toolbar"><h2>Receiving jobs <small>${rows.length} results</small></h2>${button(icon('download')+' Export','export','secondary',rows.length?'':'disabled')}</div><div class="table-scroll"><table class="jobs-table"><thead><tr><th>ASN ${icon('down')}</th><th>Job ID</th><th>Supplier</th><th>Qty</th><th>Job task</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr tabindex="0" data-action="select-job" data-asn="${r.asn}" aria-selected="${r.asn===asn}" class="${r.asn===asn?'selected':''}"><td>${icon('doc')}<b>${r.asn}</b></td><td>${r.id}</td><td>${esc(r.supplier)}</td><td>${num(M.totals(r).expected)} PCS</td><td>${M.stage(r)==='unload'?'Unload':M.stage(r)==='putaway'?'Putaway':'Confirmation'}</td><td>${jobBadge(r)}</td><td>${icon('arrow')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">'+icon('search')+'<h3>No receiving jobs found</h3><p>Try another ID or clear your filters.</p>'+button('Clear filters','clear-filters','secondary')+'</div></td></tr>'}</tbody></table></div><div class="pagination"><span>${rows.length?'1–'+rows.length:'0'} of ${rows.length}</span><button class="plain" disabled aria-label="Previous page">‹</button><span class="page-number">1</span><button class="plain" disabled aria-label="Next page">›</button></div>${selected?`<div class="selected-summary"><h3>Selected job summary</h3><div>${[['doc','PO number',j.po],['box','Total cartons',t.cartons+' cartons'],['rack','Total pallets',j.pallets.length+' pallets'],['scan','Primary material',j.material]].map(([glyph,name,value])=>`<span>${icon(glyph)}<span><small>${name}</small><b>${esc(value)}</b></span></span>`).join('')}</div></div>`:''}</section><aside class="context selected-context">${selected?`<span class="muted">Selected ASN</span><div class="selected-asn"><h2>${j.asn}</h2>${badge(j.scheduled?'Scheduled · not released':M.stage(j)==='unload'?'Ready to unload':M.stage(j)==='putaway'?'Ready for putaway':'SAP confirmation pending',j.scheduled?'gray':'green')}</div><p class="supplier-line"><span>Supplier</span>${esc(j.supplier)}</p>${sceneSlot()}${detailList(j)}<h3>Available actions</h3><div class="action-pair">${button(M.stage(j)==='unload'?'Open unload':M.stage(j)==='putaway'?'Open putaway':'View putaway','open-selected','primary',j.scheduled?'disabled':'')}${button('View ASN details','details','secondary')}</div>${j.scheduled?'<p class="muted small">Scheduled · This job has not been released.</p>':''}`:'<div class="empty-state">'+icon('doc')+'<h3>Select a receiving job</h3><p>The selected ASN and receiving dock will appear here.</p></div>'}</aside></div></section>`;}
function metric(glyph,label,value){return `<div class="operation-metric">${icon(glyph)}<span><small>${label}</small><b>${value}</b></span></div>`;}
function processRail(){const s=M.stage(job()),doneUnload=s!=='unload';return `<ol class="process-rail" aria-label="Receiving progress">${[['SAP received',true,false],['Unload',doneUnload,view==='unload'],['Putaway',s==='complete',view==='putaway'],['SAP confirmation',false,false]].map(([name,done,active],i)=>`<li class="${done?'done':active?'active':''}"><i>${done?icon('check'):i+1}</i><span>${name}</span></li>`).join('')}</ol>`;}
function operation(){const j=job(),t=M.totals(j),p=pallet(),unload=view==='unload',complete=unload?!t.remainingUnload:!t.remainingPutaway;return `<section class="operation-content"><div class="operation-heading"><div><div class="eyebrow">RECEIVING ${unload?'UNLOAD':'PUTAWAY'}</div><div class="identity"><h1>ASN ${j.asn}</h1>${badge(complete?(unload?'Unload complete':'Putaway complete'):(unload?'Unloading':'Putaway in progress'),complete?'green':unload?'amber':'blue')}</div></div>${processRail()}</div><div class="operation-summary">${unload?metric('supplier','Supplier',esc(j.supplier))+metric('box','Expected',num(t.expected)+' PCS')+metric('box','Unloaded',num(t.unloaded)+' PCS')+metric('box','Remaining',num(t.remainingUnload)+' PCS')+metric('pin','Dock',j.dock):metric('box','Unloaded',num(t.unloaded)+' PCS')+metric('rack','Put away',num(t.putaway)+' PCS')+metric('box','Remaining',num(t.remainingPutaway)+' PCS')+metric('rack','Current pallet',num(p?.qty||0)+' PCS')+metric('home','Warehouse','HKW')}</div><div class="operation-grid"><div class="operation-scene">${sceneSlot()}</div><aside class="context operation-context">${unload?unloadPanel(j,p,t):putawayPanel(j,p,t)}</aside><section class="record-section"><div class="record-tabs" role="tablist" aria-label="Receiving details">${[['records',unload?'Unload records':'Putaway records'],['objects','Related objects'],['details','ASN details'],['activity','Activity']].map(([id,title])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="tab" data-tab="${id}" id="tab-${id}" aria-controls="record-panel">${title}${id==='activity'&&j.activity.length?`<span class="tab-count">${j.activity.length}</span>`:''}</button>`).join('')}</div><div id="record-panel" role="tabpanel" aria-labelledby="tab-${tab}">${recordPanel(j)}</div></section></div></section>`;}
function unloadPanel(j,p,t){if(!p||!t.remainingUnload)return `<div class="completion-panel"><span class="completion-icon">${icon('check')}</span><h2>Unload complete</h2><p>All ${num(t.unloaded)} PCS have been recorded at receiving staging.</p>${button('Continue to putaway '+icon('arrow'),'to-putaway','primary')}<small>Next: confirm the destination for each remaining pallet.</small></div>`;return `<div class="panel-heading"><h3>Current pallet</h3>${badge(p.unloaded?'Already recorded':'Ready to record','green')}</div><h2 class="pallet-identity">${p.id}</h2><div class="object-meta"><div>${icon('box')}<span><small>Material</small><b>${esc(j.material)}</b><small>${esc(j.materialName)}</small></span></div><div>${icon('batch')}<span><small>Batch</small><b>${j.batch}</b><small>Received 28 Oct 2026</small></span></div></div><form id="unload-form" class="operation-form"><label for="quantity">Quantity</label><div class="input-unit"><input type="number" id="quantity" name="quantity" value="${p.qty}" min="1" required><span>PCS</span></div><label for="cartons">Cartons</label><input id="cartons" type="number" name="cartons" value="${p.cartons}" min="1" step="1" required><label for="staging">Staging location</label><select id="staging" name="source">${['RCV-01','RCV-02','RCV-03'].map(s=>`<option ${s===p.source?'selected':''}>${s}</option>`).join('')}</select><p id="operation-error" class="form-error" role="alert"></p><button type="submit" class="btn primary full" ${p.unloaded?'disabled':''}>${icon('download')} Record unload <kbd>Ctrl + Enter</kbd></button></form>${button(icon('alert')+' Report discrepancy','exception','secondary full')}<p class="helper-note">Record a full pallet. Use discrepancy reporting if the received goods differ.</p>`;}
function putawayPanel(j,p,t){if((!p||!t.remainingPutaway)&&j.pallets.some(p=>p.destinationStatus==='unresolved'))return `<div class="completion-panel"><h2>Historical putaway retained · mapping recovery required</h2><p>${num(t.putaway)} PCS of recorded progress is retained. Legacy destinations must be resolved before their physical locations can be confirmed.</p>${button('Recovery / export','recover-progress','secondary')}</div>`;if(!p||!t.remainingPutaway)return `<div class="completion-panel"><span class="completion-icon">${icon('check')}</span><h2>Physical putaway complete</h2><p>All ${num(t.putaway)} PCS are in their destination locations.</p>${badge('SAP confirmation pending','amber')}<small>Physical work is complete. Inventory posting has not been performed in this demo.</small>${button('View ASN details','details','secondary')}</div>`;const v=targetValidation();return `<h3>Putaway details</h3><dl class="putaway-details"><div><dt>${icon('rack')}Pallet ID</dt><dd><b>${p.id}</b></dd></div><div><dt>${icon('box')}Material</dt><dd><b>${esc(j.material)}</b><small>${esc(j.materialName)}</small></dd></div><div><dt>${icon('batch')}Batch</dt><dd>${j.batch}</dd></div><div><dt>${icon('box')}Quantity</dt><dd><b>${num(p.qty)} PCS</b><small>${p.cartons} cartons</small></dd></div><div><dt>${icon('pin')}Source location</dt><dd><b>${p.source}</b><small>Receiving staging</small></dd></div></dl><form id="putaway-form">${button('Choose Locator in rack view','choose-rack','secondary full')}<label for="destination">Destination location</label><div class="destination-input"><input id="destination" name="destination" value="${esc(destination)}" placeholder="e.g. B-03-02" autocomplete="off" required aria-describedby="location-feedback">${button(icon('scan'),'focus-location','secondary','aria-label="Focus destination scanner"')}</div><div id="location-feedback" class="location-feedback ${v.valid?'valid':'invalid'}" role="status">${icon(v.valid?'check':'alert')}<span>${esc(v.message)}</span></div><div class="recommendation"><span>${icon('pin')}<span><b>Suggested location · ${M.suggestLocation(state,p.id)||'Mapping recovery required'}</b><small>Demo rules · final confirmation revalidates</small></span></span>${button('Expected locator','recommend','secondary')}</div><p id="operation-error" class="form-error" role="alert"></p><button type="submit" class="btn primary full" data-confirm-putaway ${!v.valid||M.isPutaway(p)?'disabled':''}>Confirm putaway ${icon('arrow')}</button></form>${button(icon('alert')+' Report exception','exception','secondary full')}<div class="sap-note"><i></i><span><b>SAP confirmation pending</b><small>${num(t.remainingPutaway)} PCS remaining. Complete putaway before SAP confirmation.</small></span></div>`;}
function recordPanel(j){if(tab==='details')return `<div class="inline-details">${detailList(j)}<span>${icon('box')} ${esc(j.material)} · ${esc(j.materialName)} · Batch ${j.batch}</span></div>`;if(tab==='objects')return `<div class="related-objects">${j.pallets.map(p=>button(icon('rack')+`<span><b>${p.id}</b><small>${num(p.qty)} PCS · ${esc(M.destinationLabel(p)||p.source)}</small></span>`,'object','secondary',`data-object="${p.id}"`)).join('')}${button(icon('doc')+j.po,'object','secondary',`data-object="${j.po}"`)}</div>`;if(tab==='activity'){const entries=[...j.activity,...j.pallets.flatMap(p=>[p.unloadedAt&&!j.activity.some(e=>e.at===p.unloadedAt)?{at:p.unloadedAt,message:p.id+' · '+p.qty+' PCS unloaded to '+p.source}:null,p.putawayAt&&!j.activity.some(e=>e.at===p.putawayAt)?{at:p.putawayAt,message:p.id+' · '+p.qty+' PCS put away to '+(p.legacyDestination||M.destinationLabel(p))}:null].filter(Boolean))].sort((a,b)=>new Date(b.at)-new Date(a.at));return `<ol class="activity-list">${entries.map(e=>`<li>${icon('check')}<time>${time(e.at)}</time><span>${esc(e.message)}</span><small>Conrad</small></li>`).join('')||'<li class="muted">No activity yet.</li>'}</ol>`;}
 const unload=view==='unload',rows=j.pallets.filter(p=>unload?p.unloaded:M.isPutaway(p));
 return `<div class="table-scroll"><table class="records-table"><thead><tr><th>Pallet ID</th><th>${unload?'Material':'Destination location'}</th><th>${unload?'Batch':'Quantity'}</th><th>${unload?'Quantity':'Status'}</th><th>${unload?'Cartons':'Putaway time'}</th><th>${unload?'Staging location':'Operator'}</th>${unload?'<th>Recorded at</th><th>Status</th>':''}</tr></thead><tbody>${rows.map(p=>`<tr><td><button class="table-link" data-action="object" data-object="${p.id}">${p.id}</button></td><td>${unload?esc(j.material):esc(M.destinationLabel(p))}</td><td>${unload?j.batch:num(p.qty)+' PCS'}</td><td>${unload?num(p.qty)+' PCS':badge(p.destinationStatus==='unresolved'?'Mapping unresolved':'Completed',p.destinationStatus==='unresolved'?'amber':'green')}</td><td>${unload?p.cartons:time(p.putawayAt)}</td><td>${unload?p.source:'Conrad'}</td>${unload?`<td>${time(p.unloadedAt)}</td><td>${badge('Recorded','green')}</td>`:''}</tr>`).join('')||`<tr><td colspan="8" class="no-records">No ${unload?'unload':'putaway'} records yet.</td></tr>`}</tbody></table></div>`;
}
function time(value){if(!value)return '—';return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));}
function footer(){if(view==='rack'){selectionValid();return `<footer class="next-bar"><div><b>${selectionMode?'Putaway selection':'Read-only rack browsing'}</b><small>${selectionMode?'Return to the original task to confirm':'No business submission · Demo data'}</small></div><div class="next-actions">${button(selectionMode?'Cancel / Return to putaway':'Return to overview','rack-back','secondary')}</div></footer>`;}const j=job(),t=M.totals(j),p=pallet();let title,description,actions;
if(view==='home'){title='Next: open an '+(zone==='receiving'?'inbound':zone==='storage'?'inventory':'outbound')+' function';description=(zone==='receiving'?'Receiving':zone==='storage'?'Storage':'Dispatch')+' zone selected';actions=zone==='receiving'?button(icon('doc')+' Open Receiving Job Search '+icon('arrow'),'receiving'):button('Explore '+(zone==='storage'?'storage':'outbound')+' functions','modules','secondary');}
if(view==='receiving'){const selected=M.searchJobs(state,filters).some(r=>r.asn===asn);title=selected?'Next: '+(M.stage(j)==='unload'?'unload':'putaway')+' ASN '+j.asn:'Next: select a receiving job';description=selected?num(t.expected)+' PCS · '+t.cartons+' cartons · '+j.pallets.length+' pallets':'Search by ID or adjust your filters.';actions=button('Open '+(M.stage(j)==='unload'?'unload':'putaway')+' '+icon('arrow'),'open-selected','primary',!selected||j.scheduled?'disabled':'');}
if(view==='unload'){title=t.remainingUnload?'Next: complete remaining unload':'Next: put away received goods';description=t.remainingUnload?num(t.remainingUnload)+' PCS remaining · Record the current pallet to continue':num(t.unloaded)+' PCS unloaded · Continue with destination confirmation';actions=t.remainingUnload?button('Putaway','to-putaway','secondary','disabled')+button('Record unload '+icon('arrow'),'record-unload','primary',!p||p.unloaded?'disabled':''):button('Open putaway '+icon('arrow'),'to-putaway');}
if(view==='putaway'){title=t.remainingPutaway?'Next: confirm destination':'Physical putaway complete';description=t.remainingPutaway?(p?.id||'Select a pallet')+' · '+num(p?.qty||0)+' PCS · '+(p?.source||'RCV-02')+' → '+destination:'1 ASN processed · '+num(t.putaway)+' PCS stored · SAP confirmation pending';actions=t.remainingPutaway?`<label class="footer-destination">Destination location<input aria-label="Destination location in action bar" data-destination value="${esc(destination)}"></label>`+button('Confirm putaway '+icon('arrow'),'confirm-putaway','primary',`data-confirm-putaway ${!p||M.isPutaway(p)||!targetValidation().valid?'disabled':''}`):button('Return to receiving jobs '+icon('arrow'),'receiving');}
return `<footer class="next-bar">${icon(view==='putaway'&&!t.remainingPutaway?'check':'arrow','next-icon')}<div><b>${title}</b><small data-next-description>${esc(description)}</small></div><div class="next-actions">${actions}</div></footer>`;}
async function ensureScene(){if(scene)return scene;if(sceneFailed)return;if(scenePromise)return scenePromise;
scenePromise=window.WarehouseScene.mount(sceneHost,{onRack({physicalRackId}){if(view==='home'||view==='putaway')openRack(physicalRackId);},onLocator({locatorId}){selectLocator(locatorId);},onZone(id){if(view==='home'){zone=id;render();}},onPallet(id){const p=job().pallets.find(p=>p.id===id);if(!p)return;if(view==='home'||view==='receiving'||(view==='putaway'&&M.isPutaway(p))||(view==='unload'&&p.unloaded))return showObject(id);palletId=id;targetLocatorId='';targetTaskVersion=M.taskVersion(job());render();}}).then(value=>{scene=value;scene.setTheme(Theme.current);if(view==='login')scene.setActive(false);else updateScene();return scene;}).catch(error=>{const loading=sceneHost.querySelector('[data-scene-loading]');loading.hidden=false;loading.classList.add('error');loading.textContent='Warehouse view unavailable. '+error.message+' Forms and records remain available. Refresh the page to retry the view.';sceneFailed=true;scenePromise=null;});return scenePromise;}
function updateScene(){if(!scene)return;const visible=view!=='login'&&!!root.querySelector('[data-scene-slot]');scene.setActive(visible);if(view==='rack'){scene.showRack(rackDetail,selectedLocatorId);scene.filterRack(rackResults?.locations.map(l=>l.locatorId)||[]);return;}scene.showOverview();if(visible)scene.update({state,job:job(),view:view==='receiving'?'search':view,palletId,destination,zone});}
function render(preserveDraft=false){if(storageStatus.blocked){sceneHost.remove();scene?.setActive(false);root.innerHTML=`${header()}<main class="workspace"><section class="completion-panel" data-storage-recovery><h1>Saved progress needs recovery</h1><p class="form-error" role="alert">${esc(storageWarning)}</p>${button('Recovery / export','recover-progress','primary')} ${button('Retry saved data','retry-progress','secondary')} ${button('Reset demo','reset','secondary')}</section></main>`;return;}const draft=preserveDraft&&root.querySelector('#rack-filter-form')?new FormData(root.querySelector('#rack-filter-form')):null;const focus=view==='rack'?rackFocus():null,content=document.querySelector('.rack-content'),scroll=content?{top:document.querySelector('#page-content').scrollTop,y:scrollY}:null;sceneHost.remove();root.innerHTML=view==='login'?login():`${header()}${progressNotice()}<div class="app-layout">${rail()}<main class="workspace">${view==='rack'?'':scanBar()}<div class="page-content" id="page-content">${view==='home'?home():view==='receiving'?receiving():view==='rack'?rackPage():operation()}</div>${footer()}</main></div>`;if(draft)for(const key of ['query','queryType','levelIndex','status'])root.querySelector('#rack-filter-form').elements[key].value=draft.get(key);if(view==='rack'&&scroll){document.querySelector('#page-content').scrollTop=scroll.top;window.scrollTo(0,scroll.y);}restoreRackFocus(focus);const slot=root.querySelector('[data-scene-slot]');if(slot){slot.appendChild(sceneHost);ensureScene();}updateScene();document.title=(view==='login'?'Sign in':view==='home'?'Warehouse overview':view==='rack'?(rackDetail?.rack.label||'Rack unavailable'):view==='receiving'?'Receiving Job Search':view==='unload'?'Unload · '+asn:'Putaway · '+asn)+' | WMS';}
function route(){const [path,query='']=location.hash.replace(/^#\/?/,'').split('?'),parts=path.split('/'),allowed=['login','home','receiving','unload','putaway','rack'];let next=allowed.includes(parts[0])?parts[0]:(signedIn?'home':'login');if(!signedIn)next='login';if(signedIn&&next==='login')next='home';
 const previous=view;
 const params=new URLSearchParams(query);
 if(next==='rack'){
  selectionMode=params.get('mode')==='select';selectionNotice='';
  if(selectionMode){
   if(!selectionContext)try{selectionContext=JSON.parse(sessionStorage.getItem(selectionKey));}catch{}
   if(!selectionContext||selectionContext.returnTo!=='#/putaway/'+selectionContext.asn||!selectionContext.draft||typeof selectionContext.draft.destination!=='string'||typeof selectionContext.draft.scan!=='string'||!selectionContext.originalTarget){
    clearSelection();selectionNotice='Selection context is missing or invalid. Read-only browsing; reopen the original putaway task.';
   }else selectionValid();
  }else clearSelection();
 }
 let returning=next==='putaway'&&previous==='rack'?(pendingPutawayReturn||selectionContext):null;
 if(returning&&(parts[1]!==returning.asn||!M.validatePutawayContext(state,returning).valid))returning=null;
 pendingPutawayReturn=null;
 if(next!=='rack')clearSelection();
 if(previous==='home'&&next==='rack'){
  homeReturn={scene:scene?.getViewState(),zone,scrollTop:document.querySelector('#page-content')?.scrollTop||0,scrollY:window.scrollY};
  history.replaceState({rackReturn:homeReturn},'');
 }else if(next==='rack'&&history.state?.rackReturn)homeReturn=history.state.rackReturn;
 if(next==='rack'){
  let id=parts[1]||'';try{id=decodeURIComponent(id);}catch{}
  rackScope={sceneId:'scene-demo',physicalRackId:id,organizationId:params.get('org')||'',subinventoryId:params.get('sub')||undefined};
  selectedLocatorId=params.get('locator')||'';rackMessage='';
  rackFilters={query:'',queryType:'all',levelIndex:'',status:''};
 }else if(previous==='rack'&&next==='home'&&homeReturn)zone=homeReturn.zone;
 if(['unload','putaway'].includes(next)&&parts[1]&&M.getJob(state,parts[1]))asn=parts[1];if(['unload','putaway'].includes(next)){if(job().scheduled){next='receiving';toast('This job is scheduled and has not been released.');}else if(next==='putaway'&&M.totals(job()).remainingUnload){next='unload';toast('Complete the remaining unload before continuing.');}}
 view=next;tab='records';if(view!=='rack')pickPallet();if(returning&&view==='putaway'){asn=returning.asn;palletId=returning.palletId;destination=returning.draft.destination;targetLocatorId=M.resolveDestination(destination)||'';targetTaskVersion=returning.taskVersion;tab=returning.draft.tab||'records';zone=returning.zone;}const canonical=view==='rack'?rackHash(rackScope,selectedLocatorId):'#/'+view+(['unload','putaway'].includes(view)?'/'+asn:'');if(location.hash!==canonical)history.replaceState(history.state,'',canonical);render();
 if(view==='rack'){if(previous!=='rack')document.querySelector('#rack-title')?.focus({preventScroll:true});loadRackPage();}else {++rackRequest;++searchRequest;++inventoryRequest;}
 if(previous==='rack'&&view==='home'&&homeReturn){const saved=homeReturn;scene?.restoreViewState(saved.scene);requestAnimationFrame(()=>{if(view!=='home')return;scene?.fit();document.querySelector('#page-content').scrollTop=saved.scrollTop;window.scrollTo(0,saved.scrollY);document.querySelector('[data-action="open-rack"]')?.focus({preventScroll:true});});}
 if(returning&&view==='putaway'){
  const saved=returning;document.querySelector('#scan-input').value=saved.draft.scan;scene?.restoreViewState(saved.scene);
  requestAnimationFrame(()=>{if(view!=='putaway'||asn!==saved.asn)return;scene?.fit();document.querySelector('#page-content').scrollTop=saved.scrollTop;window.scrollTo(0,saved.scrollY);document.querySelector('#scan-input').value=saved.draft.scan;document.querySelector('#destination')?.focus({preventScroll:true});});
 }
 if(view!=='home'&&view!=='rack')homeReturn=null;
}
function showDialog(title,content){dialog.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="plain" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${content}</div>`;dialog.showModal();}
function showDetails(){const j=job();showDialog('ASN '+j.asn,`${badge(M.status(j),'blue')}<p class="muted">${esc(j.supplier)} · ${j.id}</p>${detailList(j)}<h3>Receiving progress</h3><div class="dialog-progress">${metric('box','Unloaded',num(M.totals(j).unloaded)+' PCS')}${metric('rack','Put away',num(M.totals(j).putaway)+' PCS')}</div><p>${esc(j.material)} · ${esc(j.materialName)} · Batch ${j.batch}</p><p class="helper-note">SAP confirmation has not been performed.</p>`);}
function showObject(id){const owner=state.jobs.find(j=>j.pallets.some(p=>p.id===id)||j.material===id||j.po===id);if(!owner)return toast('Object not found.');const p=owner.pallets.find(p=>p.id===id);showDialog(id,`<p class="muted">${p?'Pallet':'Related receiving object'} · ASN ${owner.asn}</p>${detailList(owner)}${p?`<dl class="detail-list"><div><dt>Quantity</dt><dd>${p.qty} PCS · ${p.cartons} cartons</dd></div><div><dt>Location</dt><dd>${esc(M.destinationLabel(p)||p.source)}</dd></div><div><dt>Status</dt><dd>${M.isPutaway(p)?(p.destinationStatus==='unresolved'?'Put away · mapping unresolved':'Put away'):p.unloaded?'Unloaded':'Pending unload'}</dd></div></dl>`:`<p>${esc(owner.material)} · ${esc(owner.materialName)}</p>`}`);}
function openSelected(){if(job().scheduled)return toast('This scheduled job has not been released.');navigate(M.stage(job())==='unload'?'unload':'putaway');}
function actionError(error){const target=document.querySelector('#operation-error');if(target)target.textContent=error.message;else toast(error.message);}
function recordUnload(){try{if(storageStatus.blocked)throw new Error(storageWarning);const form=document.querySelector('#unload-form');if(!form||!form.reportValidity())return;const data=new FormData(form);M.recordUnload(state,asn,palletId,data.get('quantity'),data.get('cartons'),data.get('source'));save();pickPallet();render();toast('Unload recorded. Receiving quantities and staging have been updated.');}catch(error){actionError(error);}}
let putawaySubmitting=false;
function confirmPutaway(){if(putawaySubmitting)return;try{if(storageStatus.blocked)throw new Error(storageWarning);refreshProgress();M.confirmPutaway(state,asn,palletId,targetLocatorId||destination,targetTaskVersion);putawaySubmitting=true;setTimeout(()=>{putawaySubmitting=false;},500);save();pickPallet();render();toast(M.totals(job()).remainingPutaway?'Putaway recorded. The next pallet is ready.':'Physical putaway complete. SAP confirmation is pending.');}catch(error){syncDestination();actionError(error);}}
function syncDestination(){document.querySelectorAll('#destination,[data-destination]').forEach(input=>input.value=destination);const p=pallet(),v=targetValidation(),feedback=document.querySelector('#location-feedback');if(feedback){feedback.className='location-feedback '+(v.valid?'valid':'invalid');feedback.innerHTML=icon(v.valid?'check':'alert')+'<span>'+esc(v.message)+'</span>';}
document.querySelectorAll('[data-confirm-putaway]').forEach(b=>b.disabled=!p||M.isPutaway(p)||!v.valid);const desc=document.querySelector('[data-next-description]');if(desc&&p)desc.textContent=p.id+' · '+p.qty+' PCS · '+p.source+' → '+destination;updateScene();}
function exportCSV(){const rows=M.searchJobs(state,filters),cells=[['ASN','Job ID','Supplier','Quantity PCS','Task','Status'],...rows.map(j=>[j.asn,j.id,j.supplier,M.totals(j).expected,M.stage(j),M.status(j)])];const csv='\uFEFF'+cells.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='receiving-jobs.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported '+rows.length+' receiving jobs.');}
function doAction(action,el){switch(action){
case 'recover-progress':recoveryDialog();break;
case 'export-progress':exportProgress();break;
case 'retry-progress':location.reload();break;
case 'theme':Theme.apply(el.dataset.themeId);break;
case 'home':navigate('home');break;
case 'open-rack':openRack(el.dataset.rackId);break;
case 'rack-back':returnFromRack();break;
case 'use-rack-location':returnFromRack(true);break;
case 'choose-rack':openRack(M.getLocatorMapping({...window.WarehouseRackData.legacyScope,locatorId:targetLocatorId||M.resolveDestination(destination)})?.physicalRackId||'rack-demo-b03');break;
case 'inventory-browser':location.hash=rackHash({physicalRackId:'',...window.WarehouseRackData.legacyScope});break;
case 'refresh-rack':loadRackPage();break;
case 'retry-inventory':loadInventory();break;
case 'more-inventory':loadInventory(true);break;
case 'more-results':loadRackResults(true);break;
case 'select-locator':selectLocator(el.dataset.locatorId);break;
case 'focus-inventory':document.querySelector('#rack-locator-info')?.focus();break;
case 'receiving':navigate('receiving');break;
case 'zone':zone=el.dataset.zone;if(view==='home')render();else navigate('home');break;
case 'open-selected':openSelected();break;
case 'open-job':asn=el.dataset.asn;openSelected();break;
case 'select-job':asn=el.dataset.asn;pickPallet();render();break;
case 'recent-asn':openSelected();break;
case 'object':showObject(el.dataset.object);break;
case 'details':showDetails();break;
case 'clear-filters':filters={query:'',type:'All objects',status:'',supplier:'',from:'',to:''};render();break;
case 'clear-scan':document.querySelector('#scan-input').value='';document.querySelector('#scan-input').focus();break;
case 'to-putaway':navigate('putaway');break;
case 'step':navigate(el.dataset.view);break;
case 'tab':tab=el.dataset.tab;render();document.querySelector('#tab-'+tab)?.focus();break;
case 'record-unload':recordUnload();break;
case 'confirm-putaway':confirmPutaway();break;
case 'focus-location':document.querySelector('#destination')?.focus();break;
case 'recommend':{const id=M.suggestLocation(state,palletId);if(!id){toast('No Demo target is available. Resolve any legacy mapping first.');break;}showDialog('Expected locator',`<p class="muted">Available location for ${esc(palletId)} · ${num(pallet()?.qty||0)} PCS</p><div class="recommended-location">${icon('rack')}<span><b>${id}</b><small>HKW · Storage · Available</small></span>${button('Use location','use-location','primary',`data-location="${id}"`)}</div><p class="helper-note">The highlighted route previews a planned move. Confirm putaway to record the destination.</p>`);break;}
case 'use-location':targetLocatorId='';destination=el.dataset.location;dialog.close();syncDestination();break;
case 'exception':showDialog(view==='unload'?'Report discrepancy':'Report exception',`<form id="exception-form"><p class="muted">ASN ${asn}${palletId?' · '+palletId:''}</p><label for="exception-type">Type</label><select id="exception-type" name="type"><option>Quantity discrepancy</option><option>Damaged packaging</option><option>Location issue</option><option>Other</option></select><label for="exception-note">Details</label><textarea id="exception-note" name="note" maxlength="500" rows="4" placeholder="Describe the issue for the next operator…" required></textarea><p class="helper-note">Saved to Activity. Quantities and locations remain unchanged.</p><p id="exception-error" class="form-error" role="alert"></p><button type="submit" class="btn primary full">Save report</button></form>`);break;
case 'export':exportCSV();break;
case 'modules':showDialog('All modules',`<p class="muted">This demo covers the receiving workflow.</p><div class="module-list"><a href="#/receiving" data-action="close-dialog">${icon('truck')}<span><b>Inbound</b><small>Receiving Job Search · Unload · Putaway</small></span>${badge('Available','green')}</a><div>${icon('arrow')}<span><b>Outbound</b><small>Picking, packing and dispatch</small></span>${badge('Outside demo','gray')}</div><div>${icon('rack')}<span><b>Storage</b><small>Inventory, counting and location management</small></span>${badge('Outside demo','gray')}</div></div>`);break;
case 'unavailable':showDialog(el.dataset.name||'Module',`<p>This function is outside the five-page demo.</p><p class="muted">Use Receiving Job Search to explore the interactive unload and putaway workflow.</p>${button('Open Receiving Job Search','dialog-receiving')}`);break;
case 'dialog-receiving':dialog.close();navigate('receiving');break;
case 'password':{const input=document.querySelector('#password');input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');break;}
case 'forgot':showDialog('Demo account access','<p>Use <b>conrad.hua</b> and <b>demo123</b> to explore this local demo.</p><p class="muted">Oracle EBS password recovery is not connected in this environment.</p>');break;
case 'close-dialog':dialog.close();break;
case 'reset':showDialog('Reset demo?',`<p>Restore the six sample jobs and their initial progress. Your local unload, putaway and exception records will be cleared.</p>${button('Reset demo','confirm-reset','primary')}`);break;
case 'confirm-reset':clearSelection();state=M.createState();storageStatus.blocked=false;storageWarning='';asn='180004521';zone='receiving';filters={query:'',type:'All objects',status:'',supplier:'',from:'',to:''};save();dialog.close();pickPallet();if(view==='home')render();else navigate('home');toast('Demo reset to its initial progress.');break;
case 'logout':clearSelection();signedIn=false;try{sessionStorage.removeItem('wms-demo-session');}catch{}navigate('login');break;
}}
document.addEventListener('wms-theme-change',e=>{
 const theme=e.detail;scene?.setTheme(theme);
 const image=document.querySelector('.login-art');if(image)image.src=theme.image;
 document.querySelectorAll('[data-theme-id]').forEach(card=>{const selected=card.dataset.themeId===theme.id;card.setAttribute('aria-pressed',String(selected));card.querySelector('.theme-selected').innerHTML=selected?icon('check')+'当前使用':'';});
});
document.addEventListener('click',e=>{const menu=document.querySelector('.theme-menu[open]');if(menu&&!menu.contains(e.target))menu.open=false;});
document.addEventListener('keydown',e=>{
 const menu=e.target.closest('.theme-menu');if(!menu)return;
 if(e.key==='Escape'){e.preventDefault();menu.open=false;menu.querySelector('summary').focus();}
 const card=e.target.closest('[data-theme-id]');if(!card)return;
 const cards=[...menu.querySelectorAll('[data-theme-id]')],index=cards.indexOf(card);
 if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();cards[e.key==='Home'?0:e.key==='End'?cards.length-1:(index+(e.key==='ArrowRight'?1:cards.length-1))%cards.length].focus();}
});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){if(el.tagName!=='A')e.preventDefault();doAction(el.dataset.action,el);}});
document.addEventListener('keydown',e=>{if(e.target.matches('tr[data-action]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();doAction(e.target.dataset.action,e.target);}if(dialog.open)return;if(signedIn&&e.ctrlKey&&e.key==='Enter'&&view==='unload'){e.preventDefault();recordUnload();}if(signedIn&&['F1','F2','F3','F4'].includes(e.key)){e.preventDefault();if(e.key==='F1')navigate('home');else if(e.key==='F2')navigate('receiving');else {zone=e.key==='F3'?'dispatch':'storage';if(view==='home')render();else navigate('home');}}});
document.addEventListener('input',e=>{if(e.target.matches('#destination,[data-destination]')){destination=e.target.value.trim();targetLocatorId='';syncDestination();}});
document.addEventListener('change',e=>{
 if(!e.target.matches('#rack-org,#rack-sub,#rack-physical'))return;
 const form=e.target.form,scope={sceneId:'scene-demo',physicalRackId:form.elements.physicalRackId.value,organizationId:form.elements.organizationId.value,subinventoryId:form.elements.subinventoryId.value||undefined};
 if(e.target.id==='rack-org'){scope.subinventoryId=undefined;scope.physicalRackId='';}
 if(e.target.id==='rack-sub')scope.physicalRackId='';
 location.hash=rackHash(scope);
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);
if(form.id==='restore-progress-form'){try{const restored=M.restore(String(data.get('recovery')));if(!restored)throw new Error('Invalid v2 data: check task identities, destination mappings and matching inventory lines. Original storage is unchanged.');M.saveState(localStorage,restored);state=restored;storageStatus.blocked=false;storageWarning='';dialog.close();route();}catch(error){document.querySelector('#recovery-error').textContent=error.message;}return;}
if(form.id==='rack-filter-form'){if(rackLoading)return;rackFilters={query:String(data.get('query')),queryType:String(data.get('queryType')),levelIndex:String(data.get('levelIndex')),status:String(data.get('status'))};selectedLocatorId='';rackInventory=null;if(inventoryScope?.locatorId!==null)inventoryScope=null;++inventoryRequest;history.replaceState(history.state,'',rackHash(rackScope));loadRackResults();if(inventoryScope)loadInventory();}
if(form.id==='login-form'){if(data.get('username')!=='conrad.hua'||data.get('password')!=='demo123'){document.querySelector('#login-error').textContent='Use the demo account conrad.hua / demo123.';return;}signedIn=true;try{sessionStorage.setItem('wms-demo-session','Conrad');}catch{}navigate('home');}
if(form.id==='scan-form'){const value=String(data.get('scan')).trim().toUpperCase();if(['unload','putaway'].includes(view)){const p=job().pallets.find(p=>p.id===value);if(!p)return toast('Pallet not found on ASN '+asn+'.');if((view==='putaway'&&M.isPutaway(p))||(view==='unload'&&p.unloaded))return toast(p.id+' has already been '+(view==='unload'?'unloaded.':'put away.'));palletId=p.id;targetLocatorId='';targetTaskVersion=M.taskVersion(job());render();toast('Selected '+p.id);return;}filters.query=value;filters.type=String(data.get('scanType'));const matches=M.searchJobs(state,filters);if(matches.length)asn=matches[0].asn;if(view==='receiving')render();else navigate('receiving');}
if(form.id==='filter-form'){if(data.get('from')&&data.get('to')&&data.get('from')>data.get('to'))return toast('Start date must be before the end date.');filters={...filters,status:String(data.get('status')),supplier:String(data.get('supplier')),from:String(data.get('from')),to:String(data.get('to'))};const matches=M.searchJobs(state,filters);if(matches.length&&!matches.some(j=>j.asn===asn))asn=matches[0].asn;render();}
if(form.id==='unload-form')recordUnload();
if(form.id==='putaway-form')confirmPutaway();
if(form.id==='exception-form'){try{if(storageStatus.blocked)throw new Error(storageWarning);M.reportException(state,asn,data.get('type'),data.get('note'));save();dialog.close();tab='activity';render();toast('Report saved to Activity.');}catch(error){document.querySelector('#exception-error').textContent=error.message;}}
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key!==M.STORAGE_KEY)return;try{refreshProgress();if(view==='rack'){selectionValid();loadRackPage();}else if(view==='putaway'){render();}}catch(error){storageWarning=error.message;storageStatus.blocked=true;clearSelection();render();}});
route();if(storageWarning&&!storageStatus.blocked)toast(storageWarning);
/* Inspection helpers used by the browser regression check. */
window.wmsDemo={rackReads,get state(){return state;},get scene(){return scene;},navigate,snapshot(){return {view,asn,palletId,destination,targetLocatorId,selectionMode,selectionContext,signedIn,theme:Theme.current.id,totals:M.totals(job()),scene:scene?.snapshot()};}};
})();
